import rclpy
from rclpy.node import Node
from bodyctrl_msgs.msg import MotorStatusMsg, CmdMotorCtrl
import matplotlib.pyplot as plt
from collections import deque

class CurrentPlotNode(Node):
    def __init__(self):
        super().__init__('plot_current_node')
        # 每个关节的kt值，对应motor_id 11~17, 21~27，下标0-13
        self.kt = [3.207, 5.632, 5.97, 5.97, 3.33, 2.16, 2.16, 
                   3.207, 5.632, 5.97, 5.97, 3.33, 2.16, 2.16]
        
        # 声明ROS2参数
        self.declare_parameter('maxlen', 1000)
        self.declare_parameter('id', 11)
        
        # 从参数中读取值
        self.maxlen = self.get_parameter('maxlen').get_parameter_value().integer_value
        self.motor_id = self.get_parameter('id').get_parameter_value().integer_value
        
        
        # Save historical current data
        self.currents = deque(maxlen=self.maxlen)
        self.cmd_currents = deque(maxlen=self.maxlen)  # 存储转换后的命令电流值
        self.time_stamps = deque(maxlen=self.maxlen)
        
        # 保存最新的命令电流值
        self.latest_cmd_current = 0.0
        
        # 获取当前电机的 kt 值
        self.motor_kt = self.get_kt_for_motor(self.motor_id)
        
        self.get_logger().info(f'参数设置: maxlen={self.maxlen}, motor_id={self.motor_id}')
        self.get_logger().info(f'当前电机kt值: {self.motor_kt}')

        self.sub_status = self.create_subscription(
            MotorStatusMsg,
            '/arm/status',
            self.status_callback,
            10
        )
        self.sub_cmd = self.create_subscription(
            CmdMotorCtrl,
            '/arm/cmd_ctrl',
            self.cmd_callback,
            10
        )

        # For live plotting
        plt.ion()
        self.fig, self.ax = plt.subplots()
        self.current_line, = self.ax.plot([], [], label=f"Actual Current (Motor {self.motor_id})", color='blue')
        self.cmd_current_line, = self.ax.plot([], [], label=f"Cmd Current (Motor {self.motor_id})", color='red')
        self.ax.set_xlabel('Sample Index')
        self.ax.set_ylabel('Current (A)')
        self.ax.legend()
        self.ax.grid(True)
        self.fig.canvas.manager.set_window_title(f'Arm Monitor - Motor {self.motor_id} (Current Comparison)')
        self.counter = 0
        
        # 创建定时器，以固定频率更新绘图（30Hz）
        self.plot_timer = self.create_timer(1.0 / 30.0, self.update_plot)
    
    def get_kt_for_motor(self, motor_id):
        """根据电机ID获取对应的kt值"""
        # motor_id 11-17 对应 kt[0-6]
        # motor_id 21-27 对应 kt[7-13]
        if 11 <= motor_id <= 17:
            idx = motor_id - 11
        elif 21 <= motor_id <= 27:
            idx = motor_id - 21 + 7
        else:
            self.get_logger().warn(f'Unknown motor_id: {motor_id}, using default kt=1.0')
            return 1.0
        return self.kt[idx]

    def status_callback(self, msg):
        # MotorStatusMsg 有 status 字段，是一个列表
        # 每个元素有 name, pos, speed, current, temperature 等字段
        current_val = 0.0
        for motor in msg.status:
            if motor.name == self.motor_id:
                current_val = motor.current
                break
        
        self.currents.append(current_val)
        self.time_stamps.append(self.counter)
        self.counter += 1
        
        # 使用最新的命令电流值添加到队列
        # 这样确保每个状态点都对应最新的命令值
        self.cmd_currents.append(self.latest_cmd_current)

    def cmd_callback(self, msg):
        # CmdMotorCtrl 有 cmds 字段，是一个列表
        # 每个元素有 name, pos, spd, tor, kp, kd 等字段
        torque_val = 0.0
        for cmd in msg.cmds:
            if cmd.name == self.motor_id:
                torque_val = cmd.tor
                break
        
        # 将力矩转换为电流：电流 = 力矩 / kt
        cmd_current_val = torque_val / self.motor_kt if self.motor_kt > 0 else 0.0
        
        # 更新最新的命令电流值
        # 这个值会在 status_callback 中被使用
        self.latest_cmd_current = cmd_current_val

    def update_plot(self):
        # Synchronize lengths - 确保所有数据长度一致
        min_len = min(len(self.time_stamps), len(self.currents), len(self.cmd_currents))
        if min_len == 0:
            return
        
        x = list(self.time_stamps)[-min_len:]
        y1 = list(self.currents)[-min_len:]
        y2 = list(self.cmd_currents)[-min_len:]
        
        self.current_line.set_data(x, y1)
        self.cmd_current_line.set_data(x, y2)
        
        # 更新坐标轴范围
        self.ax.relim()
        self.ax.autoscale_view()
        
        # 刷新绘图
        self.fig.canvas.draw()
        self.fig.canvas.flush_events()

def main(args=None):
    rclpy.init(args=args)
    node = CurrentPlotNode()
    try:
        rclpy.spin(node)
    except KeyboardInterrupt:
        pass
    finally:
        node.destroy_node()
        rclpy.shutdown()
        plt.ioff()
        plt.show()

if __name__ == '__main__':
    main()
